-- 2026-09-26: واردسازی کامل فهرست مدارس سرویس مدارس
-- منبع: Book1.xlsx | 3293 ردیف | 3292 کد مدرسه یکتا
-- اجرای مجدد امن: رکوردها بر اساس code به‌روزرسانی می‌شوند.
-- کد تکراری 95088338 در فایل ورودی دو بار وجود داشت؛ رکورد کامل‌تر نگه داشته شده است.
-- MySQL 8.x / MariaDB 10.6+

SET NAMES utf8mb4;

-- این Seed ممکن است روی دیتابیسی اجرا شود که جدول مدارس قبلاً توسط نسخه پایه ساخته شده است.
-- ستون‌های تکمیلی زیر باید قبل از UPDATE/INSERT وجود داشته باشند.
-- MySQL 8.x / MariaDB 10.6+: IF NOT EXISTS باعث اجرای مجدد امن می‌شود.
ALTER TABLE school_service_schools
  ADD COLUMN IF NOT EXISTS shift VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS education_level VARCHAR(150) NULL,
  ADD COLUMN IF NOT EXISTS school_type VARCHAR(150) NULL,
  ADD COLUMN IF NOT EXISTS activity_start VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS activity_end VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS morning_start VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS morning_end VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS afternoon_start VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS afternoon_end VARCHAR(20) NULL,
  ADD COLUMN IF NOT EXISTS driver_count INT NULL,
  ADD COLUMN IF NOT EXISTS student_count INT NULL,
  ADD COLUMN IF NOT EXISTS phone VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS latitude DECIMAL(10,7) NULL,
  ADD COLUMN IF NOT EXISTS longitude DECIMAL(10,7) NULL,
  ADD COLUMN IF NOT EXISTS status VARCHAR(80) NULL DEFAULT 'ثبت‌شده',
  ADD COLUMN IF NOT EXISTS location_registered_at DATETIME NULL;
SET @payload = FROM_BASE64('');

CREATE TABLE IF NOT EXISTS school_service_schools (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 code VARCHAR(100) NULL,
 name VARCHAR(255) NOT NULL,
 educational_district VARCHAR(80) NULL,
 gender VARCHAR(80) NULL,
 shift VARCHAR(80) NULL,
 education_level VARCHAR(150) NULL,
 school_type VARCHAR(150) NULL,
 activity_start VARCHAR(20) NULL,
 activity_end VARCHAR(20) NULL,
 morning_start VARCHAR(20) NULL,
 morning_end VARCHAR(20) NULL,
 afternoon_start VARCHAR(20) NULL,
 afternoon_end VARCHAR(20) NULL,
 driver_count INT NULL,
 student_count INT NULL,
 address TEXT NULL,
 phone VARCHAR(80) NULL,
 latitude DECIMAL(10,7) NULL,
 longitude DECIMAL(10,7) NULL,
 status VARCHAR(80) NULL DEFAULT 'ثبت‌شده',
 location_registered_at DATETIME NULL,
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 PRIMARY KEY(id), KEY idx_ss_code(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_service_companies (
 id INT AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(255) NOT NULL,
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_ssc_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_service_school_companies (
 school_id BIGINT UNSIGNED NOT NULL,
 company_id INT NOT NULL,
 is_primary TINYINT(1) NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(school_id,company_id),
 UNIQUE KEY uq_sssc_school(school_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS tmp_school_seed;
CREATE TEMPORARY TABLE tmp_school_seed (
 code VARCHAR(100) NOT NULL PRIMARY KEY,
 name VARCHAR(255) NOT NULL,
 educational_district VARCHAR(80) NULL,
 company_name VARCHAR(255) NULL,
 gender VARCHAR(80) NULL,
 shift VARCHAR(80) NULL,
 education_level VARCHAR(150) NULL,
 school_type VARCHAR(150) NULL,
 activity_start VARCHAR(20) NULL,
 activity_end VARCHAR(20) NULL,
 morning_start VARCHAR(20) NULL,
 morning_end VARCHAR(20) NULL,
 afternoon_start VARCHAR(20) NULL,
 afternoon_end VARCHAR(20) NULL,
 driver_count INT NULL,
 student_count INT NULL,
 address TEXT NULL,
 phone VARCHAR(80) NULL,
 latitude DECIMAL(10,7) NULL,
 longitude DECIMAL(10,7) NULL,
 status VARCHAR(80) NULL,
 location_registered_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO tmp_school_seed
SELECT
 r.c,
 IF(r.ni>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.n[',r.ni,']'))),NULL),
 IF(r.di>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.d[',r.di,']'))),NULL),
 IF(r.coi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.co[',r.coi,']'))),NULL),
 IF(r.gi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.g[',r.gi,']'))),NULL),
 IF(r.shi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.sh[',r.shi,']'))),NULL),
 IF(r.eli>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.el[',r.eli,']'))),NULL),
 IF(r.sti>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.st[',r.sti,']'))),NULL),
 IF(r.asi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.as[',r.asi,']'))),NULL),
 IF(r.aei>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.ae[',r.aei,']'))),NULL),
 IF(r.msi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.ms[',r.msi,']'))),NULL),
 IF(r.mei>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.me[',r.mei,']'))),NULL),
 IF(r.afi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.af[',r.afi,']'))),NULL),
 IF(r.afei>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.afe[',r.afei,']'))),NULL),
 r.dc,r.sc,
 IF(r.adi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.ad[',r.adi,']'))),NULL),
 IF(r.phi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.ph[',r.phi,']'))),NULL),
 r.lat,r.lng,
 IF(r.statusi>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.status[',r.statusi,']'))),NULL),
 CASE
   WHEN IF(r.lri>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.lr[',r.lri,']'))),NULL) IS NULL THEN NULL
   ELSE STR_TO_DATE(IF(r.lri>=0,JSON_UNQUOTE(JSON_EXTRACT(d.j,CONCAT('$.lr[',r.lri,']'))),NULL),'%Y-%m-%d %H:%i:%s')
 END
FROM JSON_TABLE(
 UNCOMPRESS(@payload),
 '$.r[*]' COLUMNS (
   c VARCHAR(100) PATH '$[0]',
   dc INT PATH '$[1]' NULL ON EMPTY,
   sc INT PATH '$[2]' NULL ON EMPTY,
   lat DECIMAL(10,7) PATH '$[3]' NULL ON EMPTY,
   lng DECIMAL(10,7) PATH '$[4]' NULL ON EMPTY,
   ni INT PATH '$[5]' NULL ON EMPTY,
   di INT PATH '$[6]' NULL ON EMPTY,
   coi INT PATH '$[7]' NULL ON EMPTY,
   gi INT PATH '$[8]' NULL ON EMPTY,
   shi INT PATH '$[9]' NULL ON EMPTY,
   eli INT PATH '$[10]' NULL ON EMPTY,
   sti INT PATH '$[11]' NULL ON EMPTY,
   asi INT PATH '$[12]' NULL ON EMPTY,
   aei INT PATH '$[13]' NULL ON EMPTY,
   msi INT PATH '$[14]' NULL ON EMPTY,
   mei INT PATH '$[15]' NULL ON EMPTY,
   afi INT PATH '$[16]' NULL ON EMPTY,
   afei INT PATH '$[17]' NULL ON EMPTY,
   adi INT PATH '$[18]' NULL ON EMPTY,
   phi INT PATH '$[19]' NULL ON EMPTY,
   statusi INT PATH '$[20]' NULL ON EMPTY,
   lri INT PATH '$[21]' NULL ON EMPTY
 )
) r
CROSS JOIN JSON_TABLE(
 UNCOMPRESS(@payload),
 '$' COLUMNS (j JSON PATH '$.d')
) d;

-- شرکت‌هایی که در فایل مدارس آمده‌اند ولی هنوز در جدول شرکت‌ها وجود ندارند.
INSERT INTO school_service_companies(name)
SELECT DISTINCT company_name
FROM tmp_school_seed
WHERE NULLIF(TRIM(company_name),'') IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM school_service_companies c
    WHERE c.name=tmp_school_seed.company_name
  );

-- همگام‌سازی اطلاعات مدارس موجود بر اساس کد.
UPDATE school_service_schools s
JOIN tmp_school_seed t ON t.code=s.code
SET
 s.name=t.name,
 s.educational_district=t.educational_district,
 s.gender=t.gender,
 s.shift=t.shift,
 s.education_level=t.education_level,
 s.school_type=t.school_type,
 s.activity_start=t.activity_start,
 s.activity_end=t.activity_end,
 s.morning_start=t.morning_start,
 s.morning_end=t.morning_end,
 s.afternoon_start=t.afternoon_start,
 s.afternoon_end=t.afternoon_end,
 s.driver_count=t.driver_count,
 s.student_count=t.student_count,
 s.address=t.address,
 s.phone=t.phone,
 s.latitude=t.latitude,
 s.longitude=t.longitude,
 s.status=t.status,
 s.location_registered_at=t.location_registered_at,
 s.is_active=1;

-- درج مدارس جدید.
INSERT INTO school_service_schools
(code,name,educational_district,gender,shift,education_level,school_type,
 activity_start,activity_end,morning_start,morning_end,afternoon_start,afternoon_end,
 driver_count,student_count,address,phone,latitude,longitude,status,location_registered_at,is_active)
SELECT
 t.code,t.name,t.educational_district,t.gender,t.shift,t.education_level,t.school_type,
 t.activity_start,t.activity_end,t.morning_start,t.morning_end,t.afternoon_start,t.afternoon_end,
 t.driver_count,t.student_count,t.address,t.phone,t.latitude,t.longitude,t.status,t.location_registered_at,1
FROM tmp_school_seed t
WHERE NOT EXISTS (
 SELECT 1 FROM school_service_schools s WHERE s.code=t.code
);

-- مدرسه ← شرکت سرویس‌دهنده
INSERT INTO school_service_school_companies(school_id,company_id,is_primary)
SELECT s.id,c.id,1
FROM school_service_schools s
JOIN tmp_school_seed t ON t.code=s.code
JOIN school_service_companies c ON c.name=t.company_name
WHERE NULLIF(TRIM(t.company_name),'') IS NOT NULL
ON DUPLICATE KEY UPDATE
 company_id=VALUES(company_id),
 is_primary=1;

DROP TEMPORARY TABLE IF EXISTS tmp_school_seed;
SET @payload=NULL;
